#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic<int> ready{0};
    std::jthread worker([&] {
        ready.store(42);
        ready.notify_one();
        ready.notify_all();
    });
    ready.wait(0);
    worker.join();
    std::cout << ready.load() << "\n";
}
